module AddressGenerator(
  input         clock,
                reset,
  input  [13:0] source_bits_addr,
  input  [7:0]  source_bits_len,
  input  [2:0]  source_bits_size,
  input  [1:0]  source_bits_burst,
  input         source_valid,
  output        source_ready,
  output [13:0] sink_bits_addr,
  output [2:0]  sink_bits_size,
  output        sink_valid,
  input         sink_ready
);

  wire        transducer_last_1;
  reg  [13:0] transducer_addr;
  reg  [7:0]  transducer_ctr;
  reg         transducer_generating;
  wire        _GEN = source_valid & transducer_generating;
  wire        _transducer_cond_WIRE_0 = _GEN & transducer_last_1;
  wire        _transducer_cond_WIRE_1 = _GEN & ~transducer_last_1;
  wire [20:0] _transducer_sink_bits_addr_T_1 =
    {7'h0, transducer_addr} << source_bits_size;
  assign transducer_last_1 =
    transducer_generating ? transducer_ctr == 8'h0 : source_bits_len == 8'h0;
  wire        _transducer_cond_WIRE_2 =
    source_valid & ~transducer_generating & transducer_last_1;
  wire        _transducer_cond_WIRE_3 =
    source_valid & ~transducer_generating & ~transducer_last_1;
  wire [3:0]  transducer_cond =
    {_transducer_cond_WIRE_3,
     _transducer_cond_WIRE_2,
     _transducer_cond_WIRE_1,
     _transducer_cond_WIRE_0};
  wire        transducer_errorAtLeastTwoActions =
    source_valid
    & (|(transducer_cond
         & {_transducer_cond_WIRE_3,
            _transducer_cond_WIRE_2,
            _transducer_cond_WIRE_1,
            _transducer_cond_WIRE_0} - 4'h1));
  wire        transducer_errorNoAction = source_valid & transducer_cond == 4'h0;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
      if ((`PRINTF_COND_) & transducer_errorAtLeastTwoActions & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: at least two actions are taken in the same clock cycle!\n");
      if ((`PRINTF_COND_) & transducer_errorAtLeastTwoActions & _transducer_cond_WIRE_0
          & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: action 'accept' @[src/main/scala/chext/amba/axi4/full/components/AddressGenerator.scala:73:32]\n");
      if ((`PRINTF_COND_) & transducer_errorAtLeastTwoActions & _transducer_cond_WIRE_1
          & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: action 'produce' @[src/main/scala/chext/amba/axi4/full/components/AddressGenerator.scala:73:32]\n");
      if ((`PRINTF_COND_) & transducer_errorAtLeastTwoActions & _transducer_cond_WIRE_2
          & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: action 'accept' @[src/main/scala/chext/amba/axi4/full/components/AddressGenerator.scala:73:32]\n");
      if ((`PRINTF_COND_) & transducer_errorAtLeastTwoActions & _transducer_cond_WIRE_3
          & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: action 'produce' @[src/main/scala/chext/amba/axi4/full/components/AddressGenerator.scala:73:32]\n");
      if ((`PRINTF_COND_) & transducer_errorNoAction & ~reset)
        $fwrite(32'h80000002,
                "elastic.Transducer: no action was taken! @[src/main/scala/chext/amba/axi4/full/components/AddressGenerator.scala:73:32]\n");
    end // always @(posedge)
  `endif // not def SYNTHESIS
  always @(posedge clock) begin
    if (source_valid) begin
      automatic logic _GEN_0;
      _GEN_0 = transducer_last_1 | ~sink_ready;
      if (transducer_generating) begin
        if (_GEN_0) begin
        end
        else begin
          if (source_bits_burst == 2'h1)
            transducer_addr <= transducer_addr + 14'h1;
          else if (source_bits_burst == 2'h2)
            transducer_addr <=
              transducer_addr & {6'h3F, ~source_bits_len} | transducer_addr + 14'h1
              & {6'h0, source_bits_len};
          transducer_ctr <= transducer_ctr - 8'h1;
        end
      end
      else if (_GEN_0) begin
      end
      else begin
        transducer_addr <= (source_bits_addr >> source_bits_size) + 14'h1;
        transducer_ctr <= source_bits_len - 8'h1;
      end
    end
    if (reset)
      transducer_generating <= 1'h0;
    else if (source_valid) begin
      if (transducer_generating)
        transducer_generating <= ~(transducer_last_1 & sink_ready);
      else
        transducer_generating <= ~transducer_last_1 & sink_ready;
    end
  end // always @(posedge)
  assign source_ready = source_valid & transducer_last_1 & sink_ready;
  assign sink_bits_addr =
    ~transducer_generating | source_bits_burst == 2'h0
      ? source_bits_addr
      : _transducer_sink_bits_addr_T_1[13:0];
  assign sink_bits_size = source_bits_size;
  assign sink_valid = source_valid;
endmodule

module StrobeGenerator(
  input  [13:0] source_bits_addr,
  input  [2:0]  source_bits_size,
  input         source_valid,
  output        source_ready,
  output [13:0] sink_bits_addr,
  output [7:0]  sink_bits_strb,
